    const cells=$$('.seq-cell',root),tempo=$('[data-range="tempo"]',root),echo=$('[data-range="echo"]',root),dissonance=$('[data-range="dissonance"]',root),volume=$('[data-range="echo-volume"]',root);
    try{const stored=JSON.parse(localStorage.getItem(patternKey)||'null');if(Array.isArray(stored)&&stored.length===3&&stored.every(row=>Array.isArray(row)&&row.length===16))stored.forEach((row,i)=>row.forEach((v,j)=>patterns[i][j]=Boolean(v)));}catch(_){}
