    function note(track,time){const freqs=[55,110,220,330,440,660],base=freqs[(step+track*2)%freqs.length],detune=1+Number(dissonance.value)/100*.032*Math.sin(step*2.2+track),osc=ac.createOscillator(),gain=ac.createGain(),filter=ac.createBiquadFilter(),delay=ac.createDelay(.5),feedback=ac.createGain(),tone=$('[data-select="tone"]',root).value;osc.type=tone==='wire'?'sawtooth':tone==='wood'?'triangle':tone==='hollow'?'sine':['sine','triangle','square'][track];osc.frequency.setValueAtTime(base*(track===1?2:track===2?4:1)*detune,time);filter.type='lowpass';filter.frequency.value=tone==='wire'?1600:tone==='wood'?850:tone==='hollow'?2300:3000;gain.gain.setValueAtTime(.0001,time);gain.gain.exponentialRampToValueAtTime(track===0?.48:.24,time+.012);gain.gain.exponentialRampToValueAtTime(.0001,time+.2);delay.delayTime.value=.075+(Number(echo.value)/100)*.24;feedback.gain.value=Number(echo.value)/100*.57;osc.connect(filter);filter.connect(gain);gain.connect(master);gain.connect(delay);delay.connect(feedback);feedback.connect(delay);delay.connect(master);osc.start(time);osc.stop(time+.25);}
