  const ideaSubjects=['a closed aquarium','a public clock','a vending machine','an abandoned sports hall','a forgotten computer','a miniature railway','a household object','a quiet airport','an unmarked doorway','a weather station','a community noticeboard','a temporary museum','a bus shelter with curtains','a swimming pool for shadows','a parcel addressed to the building','a photocopier that keeps one page','a staircase with a service desk','a small town inside a cupboard','a lost-property office for feelings','a museum of spare minutes','a lighthouse in a basement','a vending machine for directions','a public telephone with no receiver','a garden planted in a carpet','a hotel room used as a clock','a train carriage full of lamps','a map folded around a sound','a shop selling almost identical keys','a lift that stops at punctuation','a library with one returning book','a weather report for a single chair','a quiet machine in a noisy room','a door that has been moved indoors','a cinema showing the waiting room','a photograph that needs a frame','a fountain with no water','a post office for future letters','a bench reserved for nobody','a clock repairer with no clocks','a small archive of ordinary mistakes'];
